        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and o[j] > 0:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                nearest[i] = min(nearest[i], d / (r[i] + r[j]))
    weight = sum(o[i] for i in range(n) if isfinite(nearest[i]))
    if weight <= 0:
        return 0.0
    mean = sum(o[i] * nearest[i] for i in range(n) if isfinite(nearest[i])) / weight
    variance = sum(o[i] * (nearest[i] - mean) ** 2 for i in range(n) if isfinite(nearest[i])) / weight
    return sqrt(max(variance, 0.0)) / mean if mean > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    en = [(p.get(a.get('element')) or {}).get('eneg') for a in sites]
    o = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    nearest = [inf] * n
    bonds = s.get('neighbors') or []
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and o[j] > 0:
            nearest[i] = min(nearest[i], d)
    total = 0.0
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and isfinite(nearest[i]):
            if en[i] is not None and en[j] is not None:
                ratio = d / (1.4 * nearest[i])
                if ratio < 2.0:
                    total += o[i] * o[j] * (en[i] - en[j]) ** 2 * exp(-(ratio ** 6)) / d
    weight = sum(o[i] for i in range(n) if en[i] is not None)
    return total / (2.0 * weight) if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    en = [(p.get(a.get('element')) or {}).get('eneg') for a in sites]
    o = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    nearest = [inf] * n
    bonds = s.get('neighbors') or []
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and o[j] > 0:
            nearest[i] = min(nearest[i], d)
    totals = [0.0] * n
    counts = [0.0] * n
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 1e-8 < d <= 1.25 * nearest[i]:
            if en[i] is not None and en[j] is not None:
                totals[i] += o[j] * (en[j] - en[i])
                counts[i] += o[j]
    weight = sum(o[i] for i in range(n) if counts[i] > 0)
    if weight <= 0:
        return 0.0
    mean = sum(o[i] * totals[i] / counts[i] for i in range(n) if counts[i] > 0) / weight
    variance = sum(o[i] * (totals[i] / counts[i] - mean) ** 2 for i in range(n) if counts[i] > 0) / weight
    return sqrt(max(variance, 0.0))

def feature(s):
    if not s:
        return 0.0
    p = s.get('element_properties') or {}
    total = 0.0
    scale = 0.0
    for e, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        a = p.get(e) or {}
        g = a.get('group')
        en = a.get('eneg')
        v = a.get('valence_electrons')
        row = a.get('row')
        q = None
        if g == 1 or g == 2:
            q = float(g)
        elif g == 13:
            q = 3.0
        elif g == 14:
            q = -4.0 if en is not None and en >= 2.3 else 4.0
        elif g is not None and 15 <= g <= 17:
            q = float(g - 18)
        elif g == 18:
            q = 0.0
        elif v is not None and ((g is not None and 3 <= g <= 12) or (g is None and row is not None and row >= 6)):
            q = min(max(v, 0.0), 3.0)
        if q is not None:
            total += x * q
            scale += x * abs(q)
    return total / scale if scale > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3 or any(len(row) != 3 for row in matrix):
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    o = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    nearest = [inf] * n
    bonds = s.get('neighbors') or []
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and o[j] > 0:
            nearest[i] = min(nearest[i], d)
    moment = [[0.0, 0.0, 0.0] for k in range(3)]
    weight = 0.0
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 1e-8 < d <= 1.25 * nearest[i]):
            continue
        fi = sites[i].get('frac_coords')
        fj = sites[j].get('frac_coords')
        image = b.get('image')
        if fi is None or fj is None or image is None:
            continue
        delta = [fj[k] + image[k] - fi[k] for k in range(3)]
        vector = [sum(delta[k] * matrix[k][a] for k in range(3)) for a in range(3)]
        norm2 = sum(x * x for x in vector)
        w = o[i] * o[j]
        if norm2 > 1e-16 and w > 0:
            for a in range(3):
                for c in range(3):
                    moment[a][c] += w * vector[a] * vector[c] / norm2
            weight += w
    if weight <= 0:
        return 0.0
    deviation = sum((moment[a][c] / weight - (1.0 / 3.0 if a == c else 0.0)) ** 2 for a in range(3) for c in range(3))
    return sqrt(max(1.5 * deviation, 0.0))

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    valence = [(p.get(a.get('element')) or {}).get('valence_electrons') for a in sites]
    o = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    nearest = [inf] * n
    bonds = s.get('neighbors') or []
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and o[j] > 0:
            nearest[i] = min(nearest[i], d)
    counts = [0.0] * n
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 1e-8 < d <= 1.25 * nearest[i]:
            counts[i] += o[j]
    total = 0.0
    weight = 0.0
    for i in range(n):
        if counts[i] > 0 and valence[i] is not None and valence[i] >= 0:
            total += o[i] * valence[i] / max(counts[i], 1.0)
            weight += o[i]
    return total / weight if weight > 0 else 0.0
